from collections import deque
g = {1: [2, 3], 2: [4], 3: [4, 5], 4: [6], 5: [6], 6: []}
visited = [1]
q = deque([1])
while q:
    v = q.popleft()
    print(v, end=" ")
    for nxt in g[v]:
        if nxt not in visited:
            visited.append(nxt)
            q.append(nxt)

