from collections import deque
g = {"A": ["B", "C"], "B": ["D"], "C": ["D", "E"], "D": [], "E": []}
seen = {"A"}
q = deque(["A"])
order = []
while q:
    v = q.popleft()
    order.append(v)
    for n in g[v]:
        if n not in seen:
            seen.add(n)
            q.append(n)
print(order)

